# Clean and deduplicate
slugs = [s.strip() for s in companies.replace("\n", "").split(",") if s.strip()]
unique_slugs = []
seen = set()
for s in slugs:
    s_clean = s.lower().replace(" ", "-")
    if s_clean not in seen:
        seen.add(s_clean)
        unique_slugs.append(s_clean)

print(f"Total unique companies: {len(unique_slugs)}")
print(",".join(unique_slugs))
print(f"\nCount: {len(unique_slugs)}")
